  max-width: 1100px;
  margin: 0 auto;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  gap: 24px;
}
.brand {
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--accent-strong);
}
.site-header ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 18px;
}
.site-header a {
  color: var(--text-muted);
  text-decoration: none;
  padding: 6px 4px;
  border-bottom: 2px solid transparent;
}
.site-header a:hover {
  color: var(--text);
}
.site-header a[aria-current="page"] {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.preview {
  max-width: 1100px;
  margin: 0 auto;
  padding: 28px 20px 64px;
}
.preview h1 {
  margin: 0 0 4px;
  font-size: clamp(1.5rem, 1.1rem + 1.6vw, 2rem);
  letter-spacing: -0.01em;
}
.meta {
  margin: 0 0 20px;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.preview__figure {
  margin: 0;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}
.preview__figure img {
  width: 100%;
  aspect-ratio: 3 / 2;
  object-fit: cover;
}
.preview__figure figcaption {
  padding: 12px 16px;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
  font-size: 0.9rem;
}

.actions {
  margin-top: 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.btn {
  -webkit-appearance: none;
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: inherit;
  font-weight: 600;
  padding: 10px 16px;
  min-height: 40px;
  border-radius: 8px;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev-2);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.btn:hover {
  background: #232a3b;
  border-color: #4a5470;
}
.btn:active {
  transform: translateY(1px);
}

.btn--ghost {
  background: transparent;
}
.btn--ghost:hover {
  background: var(--bg-elev-2);
}

.btn--danger {
  background: var(--danger-bg);
  border-color: #5a2a30;
  color: var(--danger-strong);
}
.btn--danger:hover {
  background: #4a2026;
  border-color: #7a3a40;
  color: #ffb8b8;
}

