  margin: 0 0 8px;
  font-size: 1.2rem;
}
.dialog__desc {
  margin: 0 0 20px;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}
.dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

/* Status live region (visually hidden) */
.status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .btn {
    transition: none;
  }
