+  color: var(--text-muted);
+  border-top: 1px solid var(--border);
+  font-size: 0.9rem;
+}
+
+.actions {
+  margin-top: 18px;
+  display: flex;
+  flex-wrap: wrap;
+  gap: 10px;
+}
+
+.btn {
+  -webkit-appearance: none;
+  appearance: none;
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  font: inherit;
+  font-weight: 600;
+  padding: 10px 16px;
+  min-height: 40px;
+  border-radius: 8px;
+  border: 1px solid var(--border-strong);
+  background: var(--bg-elev-2);
+  color: var(--text);
+  cursor: pointer;
+  transition: background 0.15s, border-color 0.15s, color 0.15s;
+}
+.btn:hover {
+  background: #232a3b;
+  border-color: #4a5470;
+}
+.btn:active {
+  transform: translateY(1px);
+}
+
+.btn--ghost {
+  background: transparent;
+}
+.btn--ghost:hover {
+  background: var(--bg-elev-2);
+}
+
+.btn--danger {
+  background: var(--danger-bg);
+  border-color: #5a2a30;
+  color: var(--danger-strong);
+}
+.btn--danger:hover {
+  background: #4a2026;
+  border-color: #7a3a40;
+  color: #ffb8b8;
+}
+
+/* Dialog */
+.dialog {
+  padding: 0;
+  border: 1px solid var(--border-strong);
+  border-radius: var(--radius);
+  background: var(--bg-elev);
+  color: var(--text);
+  box-shadow: var(--shadow);
+  max-width: min(440px, calc(100vw - 32px));
+  width: 100%;
+}
+.dialog::backdrop {
+  background: rgba(5, 7, 12, 0.7);
+  backdrop-filter: blur(4px);
+}
+
+.dialog__panel {
+  padding: 24px;
+}
+.dialog__icon {
+  width: 44px;
+  height: 44px;
+  border-radius: 50%;
+  display: grid;
+  place-items: center;
+  background: var(--danger-bg);
+  color: var(--danger-strong);
+  border: 1px solid #5a2a30;
+  margin-bottom: 14px;
+}
+.dialog__title {
+  margin: 0 0 8px;
+  font-size: 1.2rem;
+}
+.dialog__desc {
+  margin: 0 0 20px;
+  color: var(--text-muted);
+  overflow-wrap: anywhere;
+}
+.dialog__actions {
+  display: flex;
+  justify-content: flex-end;
+  gap: 10px;
+  flex-wrap: wrap;
+}
+
+/* Status live region (visually hidden) */
+.status {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .btn {
+    transition: none;
+  }
+}
+
+@media (forced-colors: active) {
+  .btn,
+  .dialog {
+    border-color: ButtonBorder;
+  }
+  .btn {
+    color: ButtonText;
+    background: ButtonFace;
+  }
+  .dialog {
+    background: Canvas;
+    color: CanvasText;
+  }
+  :focus-visible {
+    outline-color: Highlight;
+  }
+}
+
')

